class ResearchGroup {
  + name : string
}

class Department {
  + name : string
}

class Researcher {
  + name : string
  + researcherId : int
}

class Project {
  + title : string
  + projectId : int
}

class WorkPackage {
  + wpId : int
  + description : string
}

Department "1" -- "*" ResearchGroup
ResearchGroup "1" -- "*" Researcher
